    if st.allowed_left(verdict) == 0 && (finish == "tool_calls" || finish == "function_call") {
        ch["finish_reason"] = "stop".into();
    }
    if st.notice_done {
        return None;
    }
    st.notice_done = true;
    Some(st.notice_text(verdict))
}

